// ============================================================================
// Background Task Execution Framework — embedded SQLite schema (server).
//
// The exact DDL for prisma/schema.prisma, generated by:
//   bunx prisma migrate diff --from-empty --to-schema-datamodel \
//     prisma/schema.prisma --script
//
// Why an embedded copy: serverless deployments resolve DATABASE_URL to a
// WRITABLE per-instance SQLite file (/tmp — see src/lib/tasks/prisma.ts),
// and a fresh file has NO tables. `prisma db push` is a dev-time CLI — it
// cannot run inside a serverless function — so ensureTasksSchema() applies
// this DDL at runtime when the TaskRun table is missing. Regenerate this
// file with the command above whenever prisma/schema.prisma changes (the
// task framework's models: TaskRun, TaskSchedule, TaskCloudConfig,
// TaskArtifact — plus the schema's User/Post examples, kept identical so
// the file never drifts from the schema).
// ============================================================================

export const TASKS_SCHEMA_SQL = `
-- CreateTable
CREATE TABLE "User" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "email" TEXT NOT NULL,
    "name" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL
);

-- CreateTable
CREATE TABLE "Post" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "title" TEXT NOT NULL,
    "content" TEXT,
    "published" BOOLEAN NOT NULL DEFAULT false,
    "authorId" TEXT NOT NULL,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL
);

-- CreateTable
CREATE TABLE "TaskRun" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "taskId" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "type" TEXT NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'queued',
    "phase" TEXT NOT NULL DEFAULT 'claim',
    "orchestrator" TEXT NOT NULL DEFAULT 'local',
    "title" TEXT,
    "prompt" TEXT NOT NULL,
    "config" TEXT NOT NULL DEFAULT '{}',
    "payload" TEXT NOT NULL DEFAULT '{"version":1,"conversation":{"id":null,"title":null,"messages":[]},"files":[]}',
    "progress" TEXT NOT NULL DEFAULT '{}',
    "chunks" TEXT NOT NULL DEFAULT '[]',
    "chunkSeq" INTEGER NOT NULL DEFAULT 0,
    "sandboxId" TEXT,
    "conversationId" TEXT,
    "scheduleId" TEXT,
    "taskTokenHash" TEXT,
    "clientSyncState" TEXT NOT NULL DEFAULT 'pending',
    "lockHolder" TEXT,
    "lockedAt" DATETIME,
    "error" TEXT,
    "attempts" INTEGER NOT NULL DEFAULT 0,
    "startedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    "finishedAt" DATETIME,
    "externalRunId" TEXT,
    CONSTRAINT "TaskRun_scheduleId_fkey" FOREIGN KEY ("scheduleId") REFERENCES "TaskSchedule" ("id") ON DELETE SET NULL ON UPDATE CASCADE
);

-- CreateTable
CREATE TABLE "TaskSchedule" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "name" TEXT NOT NULL,
    "cronExpr" TEXT NOT NULL,
    "timezone" TEXT NOT NULL DEFAULT 'UTC',
    "taskType" TEXT NOT NULL DEFAULT 'scheduled_business',
    "prompt" TEXT NOT NULL,
    "config" TEXT NOT NULL DEFAULT '{}',
    "encryptedApiKey" TEXT,
    "active" BOOLEAN NOT NULL DEFAULT true,
    "runCount" INTEGER NOT NULL DEFAULT 0,
    "lastRunAt" DATETIME,
    "nextRunAt" DATETIME,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL
);

-- CreateTable
CREATE TABLE "TaskCloudConfig" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "encryptedKey" TEXT NOT NULL,
    "maskedKey" TEXT NOT NULL,
    "taskSlug" TEXT NOT NULL DEFAULT 'agent-run',
    "accountJson" TEXT NOT NULL DEFAULT '{}',
    "encryptedWorkerToken" TEXT NOT NULL,
    "verifiedAt" DATETIME NOT NULL,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL
);

-- CreateTable
CREATE TABLE "TaskArtifact" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "runId" TEXT NOT NULL,
    "kind" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "path" TEXT,
    "mimeType" TEXT NOT NULL DEFAULT 'text/plain',
    "content" TEXT NOT NULL DEFAULT '',
    "encoding" TEXT NOT NULL DEFAULT 'utf8',
    "size" INTEGER NOT NULL DEFAULT 0,
    "truncated" BOOLEAN NOT NULL DEFAULT false,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "TaskArtifact_runId_fkey" FOREIGN KEY ("runId") REFERENCES "TaskRun" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);

-- CreateIndex
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");

-- CreateIndex
CREATE INDEX "TaskRun_userId_status_idx" ON "TaskRun"("userId", "status");

-- CreateIndex
CREATE INDEX "TaskRun_status_phase_idx" ON "TaskRun"("status", "phase");
`;
